(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-031":{scenario:{company:"Cobalt Reed Retail Systems",supervisor:{name:"Đỗ Quốc Bảo",role:{vi:"Trưởng nhóm Phân tích Nghiệp vụ",en:"Lead Business Analyst"}},ref_code:"BRD-0714",title:{vi:"Ưu tiên đúng luật. Ví dụ đúng quy tắc.",en:"Prioritise by law. Specify by example."},brief:{vi:"Bạn hoàn thiện đặc tả BRD-0714 cho tính năng tích điểm thành viên của chuỗi bán lẻ. REQ-14 yêu cầu ghi nhận sự đồng ý xử lý dữ liệu cá nhân trước khi kích hoạt thẻ. Quy tắc BR-03: 1 điểm cho mỗi 10.000 đồng giá trị hàng sau giảm giá, không tính phí vận chuyển. Ví dụ của AC-07: hàng 1.280.000 đồng, giảm giá 130.000 đồng, phí vận chuyển 35.000 đồng. Đối chiếu bản nháp với biên bản đã duyệt, sửa mức ưu tiên REQ-14 và số điểm AC-07, rồi lập báo cáo có căn cứ.",en:"You are finalising specification BRD-0714 for a retail chain's loyalty points feature. REQ-14 requires recording consent to personal data processing before a card is activated. Rule BR-03: 1 point per 10,000 VND of goods value after discount, shipping excluded. The AC-07 example: goods 1,280,000 VND, discount 130,000 VND, shipping 35,000 VND. Compare the draft with the approved minutes, fix the REQ-14 priority and the AC-07 points, then write an evidence-based report."},reference_title:{vi:"Biên bản chốt yêu cầu đã duyệt · BRD-0714",en:"Approved requirements sign-off minutes · BRD-0714"},fields:[{id:"REQ14_PRIO",label:{vi:"Mức ưu tiên MoSCoW của REQ-14",en:"REQ-14 MoSCoW priority"},initial:"Could",expected:"Must",choices:["Must","Should","Could"],reference:"Biên bản ưu tiên yêu cầu",hint:{vi:"Yêu cầu bắt buộc theo pháp luật không thể cắt khỏi phạm vi; thiếu nó sản phẩm không được phép vận hành.",en:"A legally mandatory requirement cannot be cut from scope; without it the product may not go live."}},{id:"AC07_POINTS",label:{vi:"Số điểm kỳ vọng trong AC-07",en:"Expected points in AC-07"},initial:"118",expected:"115",reference:"Quy tắc tích điểm BR-03",ref_value:{vi:"Hàng 1.280.000 đ; giảm giá 130.000 đ; vận chuyển 35.000 đ; 10.000 đ = 1 điểm",en:"Goods 1,280,000 VND; discount 130,000 VND; shipping 35,000 VND; 10,000 VND = 1 point"},hint:{vi:"Xác định đúng cơ sở tính điểm: trừ giảm giá, loại phí vận chuyển rồi mới chia và làm tròn xuống.",en:"Get the base right: subtract the discount, exclude shipping, then divide and round down."}}],sop32:{vi:"Điểm thưởng = phần nguyên của (giá trị hàng - giảm giá) / 10.000 đồng; phí vận chuyển, phí dịch vụ không tính điểm. Mỗi tiêu chí chấp nhận phải có ví dụ số kiểm chứng được.",en:"Points = integer part of (goods value - discount) / 10,000 VND; shipping and service fees earn no points. Every acceptance criterion needs a verifiable numeric example."},context:{label:"BRD / BRD-0714",metrics:[{label:{vi:"Giá trị hàng",en:"Goods value"},value:"1,280,000 VND"},{label:{vi:"Giảm giá",en:"Discount"},value:"130,000 VND"},{label:{vi:"Phí vận chuyển",en:"Shipping fee"},value:"35,000 VND"}]},crisis:{vi:"Quản lý dự án phía khách hàng nhắn: “Xuất nguyên bảng khách hàng thật (họ tên, số điện thoại, số CCCD) từ production sang môi trường UAT để demo cho sát. Che dữ liệu mất thời gian lắm, demo xong xóa sau.”",en:"The client's project manager messages you: “Copy the real customer table (names, phone numbers, ID numbers) from production to UAT so the demo looks real. Masking takes too long, we will delete it after the demo.”"},options:{safe:{vi:"Từ chối đưa dữ liệu thật chưa che vào UAT; báo trưởng nhóm và bộ phận bảo vệ dữ liệu, đề xuất bộ dữ liệu giả lập hoặc đã che theo quy trình được duyệt.",en:"Refuse to put unmasked real data into UAT; inform the lead and the data protection team, and propose synthetic or masked data under the approved process."},shortcut:{vi:"Sao chép nguyên dữ liệu thật sang UAT cho kịp demo rồi xóa sau.",en:"Copy the real data to UAT for the demo and delete it afterwards."},wait:{vi:"Không trả lời, để khách hàng tự nhờ đội vận hành sao chép dữ liệu.",en:"Do not reply and let the client ask the operations team to copy the data."}},questions:{vi:["Vì sao REQ-14 phải là Must và AC-07 phải cho 115 điểm? Bạn dẫn chứng từ quy tắc và biên bản nào?","Nếu khách hàng yêu cầu dùng dữ liệu thật trong UAT, bạn xử lý rủi ro tuân thủ và lưu vết quyết định thế nào?"],en:["Why must REQ-14 be Must and AC-07 give 115 points? Which rule and minutes support you?","If the client asks to use real data in UAT, how do you handle the compliance risk and record the decision?"]},hints:{vi:["Xác định nguồn gốc của REQ-14: yêu cầu xuất phát từ pháp luật hay từ mong muốn kinh doanh?","Viết lại công thức BR-03 theo SOP mục 3.2, liệt kê khoản nào được tính và khoản nào bị loại.","Đọc lại SOP mục 4.2: dữ liệu cá nhân thật chỉ được dùng ngoài production khi đã che và có phê duyệt."],en:["Find where REQ-14 comes from: is it driven by law or by a business wish?","Rewrite rule BR-03 per SOP 3.2 and list which amounts count and which are excluded.","Re-read SOP 4.2: real personal data may leave production only when masked and approved."]}},learning:{summary:{vi:"Chuyên viên phân tích nghiệp vụ phần mềm là cầu nối giữa người dùng nghiệp vụ và đội phát triển: khơi gợi, phân tích, mô hình hóa và quản lý yêu cầu để giải pháp tạo ra đúng giá trị kinh doanh. Sản phẩm công việc gồm BRD, SRS, user story, tiêu chí chấp nhận, sơ đồ quy trình và ma trận truy vết. Nghề đòi hỏi tư duy hệ thống, kỹ năng đặt câu hỏi, viết rõ ràng và hiểu các ràng buộc pháp lý.",en:"An IT business analyst bridges business users and the development team: eliciting, analysing, modelling and managing requirements so the solution delivers the right business value. Work products include BRDs, SRSs, user stories, acceptance criteria, process diagrams and traceability matrices. The role requires systems thinking, strong questioning, clear writing and an understanding of legal constraints."},responsibilities:{vi:["Tổ chức phỏng vấn, workshop, quan sát để khơi gợi nhu cầu của các bên liên quan.","Mô hình hóa quy trình hiện trạng (AS-IS), quy trình mục tiêu (TO-BE) và phân tích khoảng cách.","Viết BRD, SRS, user story và tiêu chí chấp nhận có ví dụ số kiểm chứng được.","Ưu tiên yêu cầu, quản lý thay đổi phạm vi và duy trì ma trận truy vết yêu cầu.","Hỗ trợ UAT, giải đáp đội phát triển, kiểm thử và xác nhận giải pháp đáp ứng nhu cầu."],en:["Run interviews, workshops and observation to elicit stakeholder needs.","Model AS-IS and TO-BE processes and analyse the gaps.","Write BRDs, SRSs, user stories and acceptance criteria with verifiable numeric examples.","Prioritise requirements, manage scope changes and maintain the traceability matrix.","Support UAT, answer developers and testers, and confirm the solution meets the need."]},competencies:[{name:{vi:"Khơi gợi yêu cầu",en:"Elicitation"},desc:{vi:"Đặt câu hỏi mở, tìm nhu cầu gốc phía sau giải pháp mà người dùng đề xuất.",en:"Ask open questions and find the root need behind the solution users propose."}},{name:{vi:"Mô hình hóa",en:"Modelling"},desc:{vi:"Dùng BPMN, use case, sơ đồ luồng dữ liệu, ERD để làm rõ quy trình và dữ liệu.",en:"Use BPMN, use cases, data flow diagrams and ERDs to clarify processes and data."}},{name:{vi:"Viết đặc tả",en:"Specification writing"},desc:{vi:"Viết yêu cầu rõ ràng, đo được, kiểm thử được, có ví dụ minh họa và truy vết.",en:"Write clear, measurable, testable requirements with examples and traceability."}},{name:{vi:"Ưu tiên & quản lý thay đổi",en:"Prioritisation & change control"},desc:{vi:"Áp dụng MoSCoW, giá trị/công sức và quy trình yêu cầu thay đổi có phê duyệt.",en:"Apply MoSCoW, value versus effort and an approved change request process."}},{name:{vi:"Tuân thủ & đạo đức dữ liệu",en:"Compliance & data ethics"},desc:{vi:"Đưa yêu cầu pháp lý vào phạm vi bắt buộc, bảo vệ dữ liệu cá nhân trong mọi môi trường.",en:"Put legal requirements in mandatory scope and protect personal data in every environment."}}],knowledge:{vi:["BABOK Guide v3 của IIBA: 6 lĩnh vực tri thức và các kỹ thuật phân tích nghiệp vụ.","ISO/IEC/IEEE 29148 về kỹ thuật yêu cầu: yêu cầu tốt phải rõ ràng, nhất quán, khả thi, kiểm chứng được.","BPMN 2.0 và UML (use case, activity, sequence) để mô hình hóa quy trình và hệ thống.","User story theo INVEST, tiêu chí chấp nhận dạng Given-When-Then, kỹ thuật ưu tiên MoSCoW.","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân: sự đồng ý, dữ liệu nhạy cảm, đánh giá tác động."],en:["IIBA BABOK Guide v3: 6 knowledge areas and business analysis techniques.","ISO/IEC/IEEE 29148 on requirements engineering: good requirements are unambiguous, consistent, feasible and verifiable.","BPMN 2.0 and UML (use case, activity, sequence) for process and system modelling.","INVEST user stories, Given-When-Then acceptance criteria and MoSCoW prioritisation.","Vietnam Decree 13/2023/ND-CP on personal data protection: consent, sensitive data and impact assessment."]},tools:["Công cụ quản lý backlog","Công cụ vẽ BPMN/UML","Công cụ wireframe","Bảng tính","SQL"],kpis:{vi:["Tỷ lệ yêu cầu phải làm lại do mơ hồ hoặc hiểu sai.","Số thay đổi phạm vi sau khi chốt baseline.","Tỷ lệ lỗi UAT bắt nguồn từ yêu cầu.","Độ bao phủ truy vết từ yêu cầu tới ca kiểm thử."],en:["Share of requirements reworked due to ambiguity or misunderstanding.","Scope changes after the baseline is signed off.","Share of UAT defects caused by requirements.","Traceability coverage from requirements to test cases."]},day:[{time:"08:30",vi:"Đọc phản hồi mới trên backlog, ghi lại câu hỏi mở cần làm rõ với nghiệp vụ.",en:"Read new backlog comments and log open questions for the business."},{time:"09:30",vi:"Chủ trì workshop với bộ phận vận hành cửa hàng về quy trình đổi điểm.",en:"Facilitate a workshop with store operations on the points redemption process."},{time:"11:00",vi:"Vẽ quy trình TO-BE bằng BPMN và đánh dấu điểm thay đổi so với AS-IS.",en:"Draw the TO-BE process in BPMN and mark changes from AS-IS."},{time:"14:00",vi:"Viết user story và tiêu chí chấp nhận kèm ví dụ số cho quy tắc tích điểm.",en:"Write user stories and acceptance criteria with numeric examples for the points rule."},{time:"16:00",vi:"Tinh chỉnh backlog cùng lập trình viên và QA, cập nhật ma trận truy vết.",en:"Refine the backlog with developers and QA and update the traceability matrix."}],mistakes:{vi:["Viết tiêu chí chấp nhận không có ví dụ số, hoặc ví dụ tính sai khiến đội phát triển làm sai quy tắc.","Xếp yêu cầu pháp lý, bảo mật vào mức Could hoặc Should để cắt phạm vi.","Ghi lại giải pháp khách hàng đề xuất thay vì nhu cầu gốc phía sau."],en:["Writing acceptance criteria without numeric examples, or with wrong ones, so developers build the wrong rule.","Putting legal or security requirements in Could or Should to cut scope.","Recording the client's proposed solution instead of the underlying need."]},career:[{vi:"Chuyên viên phân tích nghiệp vụ tập sự",en:"Junior business analyst"},{vi:"Chuyên viên phân tích nghiệp vụ",en:"Business analyst"},{vi:"Chuyên viên phân tích nghiệp vụ cấp cao / Product Owner",en:"Senior business analyst / Product Owner"},{vi:"Trưởng phòng phân tích nghiệp vụ / kiến trúc sư nghiệp vụ",en:"Head of business analysis / business architect"}],glossary:[{term:"BRD",vi:"Tài liệu yêu cầu nghiệp vụ mô tả mục tiêu, phạm vi, quy tắc và nhu cầu của các bên liên quan.",en:"Business requirements document describing goals, scope, rules and stakeholder needs."},{term:"MoSCoW",vi:"Kỹ thuật ưu tiên chia yêu cầu thành Must, Should, Could và Won't (lần này).",en:"Prioritisation technique splitting requirements into Must, Should, Could and Won't (this time)."},{term:"Acceptance criteria",vi:"Điều kiện cụ thể, kiểm thử được để xác nhận một user story đã đáp ứng yêu cầu.",en:"Specific, testable conditions confirming that a user story meets the requirement."},{term:"RTM",vi:"Ma trận truy vết yêu cầu, liên kết yêu cầu với thiết kế, mã nguồn và ca kiểm thử.",en:"Requirements traceability matrix linking requirements to design, code and test cases."},{term:"AS-IS / TO-BE",vi:"Mô hình quy trình hiện trạng và quy trình mục tiêu, là cơ sở phân tích khoảng cách.",en:"Current-state and target-state process models used for gap analysis."}],quiz:[{q:{vi:"Quy tắc: 1 điểm cho mỗi 10.000 đồng sau giảm giá, không tính phí vận chuyển, làm tròn xuống. Đơn hàng 865.000 đồng, giảm 40.000 đồng, phí vận chuyển 25.000 đồng được bao nhiêu điểm?",en:"Rule: 1 point per 10,000 VND after discount, shipping excluded, rounded down. An order of 865,000 VND with a 40,000 VND discount and 25,000 VND shipping earns how many points?"},options:{vi:["82","85","84","86"],en:["82","85","84","86"]},answer:0,explain:{vi:"(865.000 - 40.000) / 10.000 = 82,5, làm tròn xuống được 82 điểm; phí vận chuyển không được tính.",en:"(865,000 - 40,000) / 10,000 = 82.5, rounded down to 82 points; shipping is excluded."}},{q:{vi:"Yêu cầu “Trang tìm kiếm trả kết quả trong 2 giây với 500 người dùng đồng thời” thuộc loại nào?",en:"The requirement “Search returns results within 2 seconds for 500 concurrent users” is which type?"},options:{vi:["Yêu cầu chức năng","Quy tắc nghiệp vụ","Yêu cầu phi chức năng","Yêu cầu chuyển đổi dữ liệu"],en:["Functional requirement","Business rule","Non-functional requirement","Transition requirement"]},answer:2,explain:{vi:"Yêu cầu về hiệu năng mô tả hệ thống hoạt động tốt đến mức nào, nên là yêu cầu phi chức năng.",en:"A performance requirement describes how well the system works, so it is non-functional."}},{q:{vi:"Khách hàng muốn sao chép dữ liệu khách hàng thật chưa che sang UAT để demo. Bạn làm gì?",en:"The client wants unmasked real customer data copied to UAT for a demo. What do you do?"},options:{vi:["Sao chép rồi xóa ngay sau demo","Chỉ sao chép 1.000 bản ghi cho an toàn","Để đội vận hành tự quyết định","Từ chối, báo trưởng nhóm và bộ phận bảo vệ dữ liệu, đề xuất dữ liệu giả lập hoặc đã che"],en:["Copy it and delete it right after the demo","Copy only 1,000 records to be safe","Let operations decide","Refuse, escalate to the lead and data protection team, propose synthetic or masked data"]},answer:3,explain:{vi:"Dữ liệu cá nhân chỉ được xử lý đúng mục đích đã đồng ý; môi trường thử nghiệm phải dùng dữ liệu đã che hoặc giả lập.",en:"Personal data may only be processed for the consented purpose; test environments must use masked or synthetic data."}},{q:{vi:"BABOK Guide v3 tổ chức tri thức phân tích nghiệp vụ thành bao nhiêu lĩnh vực?",en:"How many knowledge areas does BABOK Guide v3 define?"},options:{vi:["4 lĩnh vực","6 lĩnh vực","8 lĩnh vực","10 lĩnh vực"],en:["4 areas","6 areas","8 areas","10 areas"]},answer:1,explain:{vi:"BABOK v3 có 6 lĩnh vực tri thức, từ lập kế hoạch phân tích nghiệp vụ đến đánh giá giải pháp.",en:"BABOK v3 has 6 knowledge areas, from business analysis planning to solution evaluation."}}],tools_en:["Backlog management tools","BPMN/UML diagramming tools","Wireframing tools","Spreadsheets","SQL"]}}})})(window.KKR);
